import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import {
  StyledContainer,
  StyledIndicator,
  StyledLabel,
  StyledRadioItem,
} from '../Radio.styles';
import type { RadioItemProps } from '../Radio.types';

export const RadioItem = React.forwardRef<
  React.ElementRef<typeof StyledRadioItem>,
  RadioItemProps
>(
  (
    { disabled = false, id, label, value, ...props },
    forwardedRef,
  ): JSX.Element => (
    <StyledContainer>
      <StyledRadioItem
        {...omitTransientProps(props)}
        ref={forwardedRef}
        disabled={disabled}
        id={id}
        value={value}
      >
        <StyledIndicator $disabled={disabled} />
      </StyledRadioItem>
      <StyledLabel $disabled={disabled} htmlFor={id}>
        {label}
      </StyledLabel>
    </StyledContainer>
  ),
);

RadioItem.displayName = 'Radio.Item';
